# Surah Yusuf (chapter 12) — part 8: ayat 71-80 (IDs 1667-1676)
SURAH = 12

ENTRIES = {
1667: (
"انہوں نے — کہا — اور — وہ — ان — پر — آئے — تم کیا تلاش — کر رہے ہو",
"""۱۔ کاروان — والے — بھائیوں — سے پوچھتے ہیں۔
۲۔ ’’قَالُوا وَأَقْبَلُوا عَلَيْهِم مَّاذَا تَفْقِدُونَ‘‘ — انہوں نے — کہا — اور — وہ — ان — پر — آئے — تم کیا تلاش — کر رہے ہو — یعنی انہوں نے کہا — اور وہ ان پر آئے — تم — کیا — تلاش کر رہے ہو۔
۳۔ عملی سبق: اہلِ انصاف — پوچھ گچھ — ضرور کرتے ہیں۔"""
),
1668: (
"انہوں نے — کہا — ہم — بادشاہ کا پیالہ — تلاش کر رہے ہیں — اور — جو — اسے — لائے گا — اس کے لیے — ایک اونٹ — کا — غلہ — ہے — اور — میں — اس — کا — ضامن — ہوں",
"""۱۔ ملازم — اعلان کرتے ہیں — بادشاہ کا پیالہ — چوری ہوا۔
۲۔ ’’قَالُوا نَفْقِدُ صُوَاعَ الْمَلِكِ وَلِمَن جَاءَ بِهِ حِمْلُ بَعِيرٍ وَأَنَا بِهِ زَعِيمٌ‘‘ — انہوں نے — کہا — ہم — بادشاہ کا پیالہ — تلاش کر رہے ہیں — اور — جو — اسے — لائے گا — اس کے لیے — ایک اونٹ — کا — غلہ — ہے — اور — میں — اس — کا — ضامن — ہوں — یعنی انہوں نے کہا — ہم بادشاہ کا پیالہ — تلاش کر رہے ہیں — اور — جو — اسے لائے گا — اس کے لیے — ایک اونٹ — کا — غلہ — ہے — اور میں اس کا — ضامن — ہوں۔
۳۔ عملی سبق: انعام — تعینات — ہونے — تو — طلب — میں — تیزی — آتی ہے۔"""
),
1669: (
"انہوں نے — کہا — اللہ کی قسم — یقیناً — تم — جانتے ہو — ہم — اس لیے نہیں آئے — کہ — زمین — میں فساد کریں — اور — نہ — ہم — چور — ہیں",
"""۱۔ بھائی — دو بار چارج — کا — تردید کرتے ہیں۔
۲۔ ’’قَالُوا تَاللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِي الْأَرْضِ وَمَا كُنَّا سَارِقِينَ‘‘ — انہوں نے — کہا — اللہ کی قسم — یقیناً — تم — جانتے ہو — ہم — اس لیے نہیں آئے — کہ — زمین — میں فساد کریں — اور — نہ — ہم — چور — ہیں — یعنی انہوں نے کہا — اللہ — کی قسم — یقیناً تم — جانتے ہو — ہم — اس — لیے — نہیں آئے — کہ زمین میں فساد کریں — اور نہ — ہم — چور — ہیں۔
۳۔ عملی سبق: بے قصور — لوگ — قسم — اٹھا کر صافی کا اظہار — کرتے ہیں۔"""
),
1670: (
"انہوں نے کہا — پس — اس کی کیا سزا — ہے — اگر — تم جھوٹے — ہو",
"""۱۔ ملازم — بھائیوں — سے سزا کا پوچھتا ہے۔
۲۔ ’’قَالُوا فَمَا جَزَاؤُهُ إِن كُنتُمْ كَاذِبِينَ‘‘ — انہوں نے کہا — پس — اس کی کیا سزا — ہے — اگر — تم جھوٹے — ہو — یعنی انہوں نے کہا — پس — اس کی کیا — سزا ہے — اگر — تم — جھوٹے ہو۔
۳۔ عملی سبق: شرعی ضابطے — ہر — جرم — کی — سزا — متعین — ہونی چاہیے۔"""
),
1671: (
"انہوں نے — کہا — اس کی سزا — یہی ہے کہ — جس کے سامان — میں — وہ — ملے — وہی — اس — کی سزا — ہے — اسی طرح — ہم — ظالموں — کو — سزا — دیتے ہیں",
"""۱۔ بھائی — خود — قانون بتاتے ہیں — جس کے سامان میں — چوری کا مال — ملے — وہ — غلام — بنے۔
۲۔ ’’قَالُوا جَزَاؤُهُ مَن وُجِدَ فِي رَحْلِهِ فَهُوَ جَزَاؤُهُ كَذَٰلِكَ نَجْزِي الظَّالِمِينَ‘‘ — انہوں نے — کہا — اس کی سزا — یہی ہے کہ — جس کے سامان — میں — وہ — ملے — وہی — اس — کی سزا — ہے — اسی طرح — ہم — ظالموں — کو — سزا — دیتے ہیں — یعنی انہوں نے کہا — اس کی سزا — یہی — ہے — کہ جس — کے سامان میں — وہ — ملے — وہی — اس — کی سزا ہے — اسی طرح — ہم — ظالموں — کو — سزا — دیتے ہیں۔
۳۔ عملی سبق: جو — قانون — آپ دوسروں پر — لگاتے ہیں — ہوشیار — رہیں۔"""
),
1672: (
"پھر — یوسفؑ — نے — ان — کے سامان — سے — پہلے — شروع کیا — بینیامین کے سامان — سے پہلے — پھر — اس نے — اسے — اپنے — بھائی — کے سامان — سے — نکالا — اسی طرح — ہم — نے — یوسفؑ — کے لیے — منصوبہ — کھیلا — بادشاہ کے قانون میں — وہ — اپنے بھائی — کو — پکڑنا — نہیں — کر سکتا تھا — مگر — اللہ — نے چاہا — ہم — جسے — چاہتے ہیں — درجوں میں — بلند کرتے ہیں — اور — ہر علم والے — سے — بڑا — علیم — ہے",
"""۱۔ یوسفؑ — تلاشی میں — بھائیوں کے سامان — سے — شروع کرتے ہیں؛ حکمت — سے پیالہ — بینیامین — کے سامان سے نکالا جاتا ہے۔
۲۔ ’’فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَاءِ أَخِيهِ ثُمَّ اسْتَخْرَجَهَا مِن وِعَاءِ أَخِيهِ كَذَٰلِكَ كِدْنَا لِيُوسُفَ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِي دِينِ الْمَلِكِ إِلَّا أَن يَشَاءَ اللَّهُ نَرْفَعُ دَرَجَاتٍ مَّن نَّشَاءُ وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ‘‘ — پھر — یوسفؑ — نے — ان — کے سامان — سے — پہلے — شروع کیا — بینیامین کے سامان — سے پہلے — پھر — اس نے — اسے — اپنے — بھائی — کے سامان — سے — نکالا — اسی طرح — ہم — نے — یوسفؑ — کے لیے — منصوبہ — کھیلا — بادشاہ کے قانون میں — وہ — اپنے بھائی — کو — پکڑنا — نہیں — کر سکتا تھا — مگر — اللہ — نے چاہا — ہم — جسے — چاہتے ہیں — درجوں میں — بلند کرتے ہیں — اور — ہر علم والے — سے — بڑا — علیم — ہے — یعنی یوسفؑ نے — ان — کے سامان — سے — پہلے — تلاشی — شروع کی — ان — کے بھائی — کے سامان سے پہلے — پھر — اس نے — اسے — اپنے بھائی — کے سامان — سے — نکالا — اسی طرح — ہم — نے — یوسفؑ — کے لیے — تدبیر — کی — بادشاہ — کے قانون میں — وہ — اپنے بھائی — کو — نہیں پکڑ سکتا تھا — مگر — اللہ نے — چاہا — ہم — جس کو — چاہتے ہیں — درجو ں میں — بلند کرتے ہیں — اور — ہر علم والے — سے — بڑا — علیم — ہے۔
۳۔ عملی سبق: اللہ — کی — تدبیر — بہترین — ہے؛ اس — پر — یقین — رکھیں۔"""
),
1673: (
"انہوں نے — کہا — اگر — اس — نے — چوری کی — تو — اس — سے پہلے — اس — کے بھائی — نے — چوری کی ہے — پس — یوسفؑ — نے — اسے — اپنے دل میں — چھپالیا — اور — ان سے ظاہر نہ کیا — اس — نے کہا — تم — حقیقت — میں — سب — سے — بری — جگہ — پر ہو — اور — اللہ — کو — تمہاری — بیان کردہ — بات کا — علم — ہے",
"""۱۔ بھائی — یوسفؑ — کی — غیرموجودگی کا خوف — دباتے ہیں؛ یوسفؑ خاموش — رہتے ہیں۔
۲۔ ’’قَالُوا إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌ لَّهُ مِن قَبْلُ فَأَسَرَّهَا يُوسُفُ فِي نَفْسِهِ وَلَمْ يُبْدِهَا لَهُمْ قَالَ أَنتُمْ شَرٌّ مَّكَانًا وَاللَّهُ أَعْلَمُ بِمَا تَصِفُونَ‘‘ — انہوں نے — کہا — اگر — اس — نے — چوری کی — تو — اس — سے پہلے — اس — کے بھائی — نے — چوری کی ہے — پس — یوسفؑ — نے — اسے — اپنے دل میں — چھپالیا — اور — ان سے ظاہر نہ کیا — اس — نے کہا — تم — حقیقت — میں — سب — سے — بری — جگہ — پر ہو — اور — اللہ — کو — تمہاری — بیان کردہ — بات کا — علم — ہے — یعنی انہوں نے کہا — اگر — اس — نے — چوری — کی — تو — اس نے نہیں — اس — کے بھائی — نے — چوری — کی — یوسفؑ نے — اس — بات — کو اپنے دل — میں رکھ لیا — اور — ان کو ظاہر — نہ کیا — اس نے — کہا — تم حقیقت — میں — سب — سے — بری جگہ — پر ہو — اور اللہ — بے تحاشہ — جانتا ہے — کیا — تم بیان — کر رہے ہو۔
۳۔ عملی سبق: دل — کی بات — اللہ — جانتا — ہے؛ سچ — چھپانے — سے — فائدہ — نہیں۔"""
),
1674: (
"انہوں نے — کہا — اے — عزیز — اس — کا — باپ — شیخ — ہے — بڑا — ہے — اس — لیے — اس — کے — بجائے — ہم میں — سے ایک — لے لیجیے — بے شک — ہم — آپ کو — نیکی — کرنے والوں — میں — دیکھتے — ہیں",
"""۱۔ بھائی — بدل — دینے — کی — اپیل — کرتے ہیں۔
۲۔ ’’قَالُوا يَا أَيُّهَا الْعَزِيزُ إِنَّ لَهُ أَبًا شَيْخًا كَبِيرًا فَخُذْ أَحَدَنَا مَكَانَهُ إِنَّا نَرَاكَ مِنَ الْمُحْسِنِينَ‘‘ — انہوں نے — کہا — اے — عزیز — اس — کا — باپ — شیخ — ہے — بڑا — ہے — اس — لیے — اس — کے — بجائے — ہم میں — سے ایک — لے لیجیے — بے شک — ہم — آپ کو — نیکی — کرنے والوں — میں — دیکھتے — ہیں — یعنی انہوں نے کہا — اے عزیز — اس کا باپ — بوڑھا — ہے — اس — کے بجائے — ہم — میں سے کوئی ایک — لے لیجیے — بے شک — ہم — آپ — کو — نیکی — کرنے والوں — میں — دیکھتے ہیں۔
۳۔ عملی سبق: عاجزی — اور — اپیل — بعض اوقات — کارگر — ہوتی ہے۔"""
),
1675: (
"یوسفؑ نے — کہا — اللہ — کی پناہ — کہ — ہم — اسے — پکڑیں — جس — کے — سامان — میں — ہماری چیز ملی — بے شک — اس صورت — میں — ہم — ظالم — ہیں",
"""۱۔ یوسفؑ — بدل دینے سے — انکار کرتے ہیں — قانون — کی پابندی۔
۲۔ ’’قَالَ مَعَاذَ اللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَاعَنَا عِندَهُ إِنَّا إِذًا لَّظَالِمُونَ‘‘ — یوسفؑ نے — کہا — اللہ — کی پناہ — کہ — ہم — اسے — پکڑیں — جس — کے — سامان — میں — ہماری چیز ملی — بے شک — اس صورت — میں — ہم — ظالم — ہیں — یعنی یوسفؑ نے کہا — اللہ کی پناہ — ہم اس — کو — گرفتار — کریں — جس کے — سامان — میں — ہماری — چیز — ملی — بے شک — اس — صورت — میں ہم — ظالم — ہیں۔
۳۔ عملی سبق: صحیح — قانون کی پیروی — کرنا — ضروری — ہے۔"""
),
1676: (
"پس — جب — وہ — اس سے — مایوس ہو گئے — الگ — بیٹھ گئے — سرگوشی کرنے — لگے — ان میں — سے سب سے بڑے نے کہا — کیا — تم نہیں جانتے — تمہارے باپ — نے — تم سے — اللہ کی قسم — کا عہد — لیا تھا — اور — اس سے پہلے — تم نے یوسفؑ — میں — کوتاہی — کی — پس — میں — اس زمین کو — ہرگز — نہیں چھوڑوں گا — یہاں تک کہ — میرے والد — مجھے — اجازت دیں — یا — اللہ — میرے — حق میں — فیصلہ — کرے — اور — وہ — بہترین — فیصلہ کرنے والے — ہیں",
"""۱۔ بھائی — مایوس — ہو کر — الگ بیٹھ گئے؛ سب سے بڑے — نے مصر — میں ہی — رہنے کا فیصلہ کیا۔
۲۔ ’’فَلَمَّا اسْتَيْئَسُوا مِنْهُ خَلَصُوا نَجِيًّا قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوا أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًا مِّنَ اللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِي يُوسُفَ فَلَنْ أَبْرَحَ الْأَرْضَ حَتَّىٰ يَأْذَنَ لِي أَبِي أَوْ يَحْكُمَ اللَّهُ لِي وَهُوَ خَيْرُ الْحَاكِمِينَ‘‘ — پس — جب — وہ — اس سے — مایوس ہو گئے — الگ — بیٹھ گئے — سرگوشی کرنے — لگے — ان میں — سے سب سے بڑے نے کہا — کیا — تم نہیں جانتے — تمہارے باپ — نے — تم سے — اللہ کی قسم — کا عہد — لیا تھا — اور — اس سے پہلے — تم نے یوسفؑ — میں — کوتاہی — کی — پس — میں — اس زمین کو — ہرگز — نہیں چھوڑوں گا — یہاں تک کہ — میرے والد — مجھے — اجازت دیں — یا — اللہ — میرے — حق میں — فیصلہ — کرے — اور — وہ — بہترین — فیصلہ کرنے والے — ہیں — یعنی پس — جب — وہ — اس سے — مایوس ہو گئے — الگ — بیٹھ گئے — سرگوشی — کرتے — ہوئے — ان میں — سے سب سے بڑے نے کہا — کیا — تم — نہیں — جانتے ہو کہ — تمہارے — باپ — نے — تم — سے — اللہ — کے واسطے — عہد — لیا — تھا — اور اس سے پہلے — تم نے — یوسفؑ — میں — کوتاہی — کی — پس میں — اس — زمین — کو — ہرگز — نہیں — چھوڑوں گا — یہاں تک — کہ — میرے — والد — مجھے — اجازت — دیں — یا — اللہ — میرے — حق — میں فیصلہ کرے — اور — وہ — بہترین — فیصلہ — کرنے والے — ہیں۔
۳۔ عملی سبق: ذمہ داری — کے — احساس — سے — انسان — اپنی جگہ پر — ڈٹا رہتا ہے۔"""
),
}
